'use strict';
// Posting preferences are independent of interface language and scoped to the account.
const postingLanguageUI={catalogue:null,loading:null,lookup:new Map(),draft:new Set(),limit:60,opener:null};
const postingLanguagePriority=['en','de','fr','es','pt','it','nl','pl','uk','ar','zh','ja','ko','hi','tr','ru','sv'];
const postingLanguageNames=new Map();
function postingLanguageName(code){const key=I18n.locale+':'+code;if(postingLanguageNames.has(key))return postingLanguageNames.get(key);let name;try{name=new Intl.DisplayNames([I18n.locale],{type:'language',fallback:'none'}).of(code);}catch{}name=name||postingLanguageUI.lookup.get(code)?.name||code;postingLanguageNames.set(key,name);return name;}
function postingLanguageSummary(selection=postingLanguages,limit=3){const codes=[...selection];if(!codes.length)return I18n.text('Any language');return codes.slice(0,limit).map(postingLanguageName).join(', ')+(codes.length>limit?` +${codes.length-limit}`:'');}
function postingLanguageMatches(job){return !postingLanguages.size||(job.postingLanguages||[]).some(code=>postingLanguages.has(code));}
function renderPostingLanguageControls(){for(const button of $$('[data-posting-languages]'))button.setAttribute('aria-label',I18n.text('Posting languages')+': '+postingLanguageSummary());for(const el of $$('[data-posting-language-summary]')){el.textContent=postingLanguageSummary(postingLanguages,el.closest('.search-config')?2:3);el.title=[...postingLanguages].map(postingLanguageName).join(', ')||I18n.text('Any language');}}
async function loadPostingLanguageCatalogue(){if(postingLanguageUI.catalogue)return postingLanguageUI.catalogue;if(postingLanguageUI.loading)return postingLanguageUI.loading;postingLanguageUI.loading=(async()=>{const response=await fetch('assets/posting-languages.json');if(!response.ok)throw Error('Language catalogue unavailable');const rows=await response.json();const catalogue=rows.map(([code,name,iso,alias,native])=>({code,name,iso,alias,native}));for(const row of catalogue)postingLanguageUI.lookup.set(row.code,row);postingLanguageUI.catalogue=catalogue;postingLanguageNames.clear();return catalogue;})().finally(()=>postingLanguageUI.loading=null);return postingLanguageUI.loading;}
function normalizeLanguageSearch(value){return value.normalize('NFKD').replace(/\p{M}/gu,'').toLocaleLowerCase().trim();}
function renderPostingLanguageChoices(reset=false){const ui=postingLanguageUI;if(!ui.catalogue)return;if(reset)ui.limit=60;const query=normalizeLanguageSearch($('#posting-language-find').value);const selected=[...ui.draft];$('#posting-language-chips').innerHTML=selected.map(code=>`<button type="button" class="posting-language-chip" data-remove-posting-language="${code}" aria-label="${I18n.text('Remove language')}: ${escapeHTML(postingLanguageName(code))}"><span data-no-translate>${escapeHTML(postingLanguageName(code))}</span><span aria-hidden="true">×</span></button>`).join('');$('#posting-language-chips').hidden=!selected.length;$('#posting-language-any').setAttribute('aria-pressed',String(!selected.length));$('#posting-language-count').textContent=`${selected.length} ${I18n.text('selected')}`;
const priority=[I18n.browserLanguage(),...postingLanguagePriority];const rows=ui.catalogue.filter(row=>!query||normalizeLanguageSearch([row.name,row.native,row.code,row.iso,row.alias,postingLanguageName(row.code)].join(' ')).includes(query));if(!query)rows.sort((a,b)=>{const ai=priority.indexOf(a.code),bi=priority.indexOf(b.code);return (ai<0?999:ai)-(bi<0?999:bi)||postingLanguageName(a.code).localeCompare(postingLanguageName(b.code),I18n.locale);});else rows.sort((a,b)=>{const exact=row=>[row.code,row.iso,row.alias,row.name,postingLanguageName(row.code),row.native].some(v=>normalizeLanguageSearch(v||'')===query);return Number(exact(b))-Number(exact(a))||postingLanguageName(a.code).localeCompare(postingLanguageName(b.code),I18n.locale);});
$('#posting-language-choices').innerHTML=rows.slice(0,ui.limit).map(row=>{const name=postingLanguageName(row.code),other=[row.native,row.name].filter((v,i,a)=>v&&v!==name&&a.indexOf(v)===i).join(' · ');return `<label class="posting-language-choice"><input type="checkbox" value="${row.code}" ${ui.draft.has(row.code)?'checked':''}><span data-no-translate><b>${escapeHTML(name)}</b>${other?`<small>${escapeHTML(other)}</small>`:''}</span><span class="posting-language-code" data-no-translate>${row.code.toUpperCase()}</span></label>`;}).join('');$('#posting-language-empty').hidden=!!rows.length;$('#posting-language-more').hidden=rows.length<=ui.limit;$('#posting-language-load-state').hidden=true;$('#posting-language-done').disabled=false;
}
async function openPostingLanguagePicker(){const ui=postingLanguageUI;ui.draft=new Set(postingLanguages);ui.opener=document.activeElement;ui.limit=60;$('#posting-language-find').value='';$('#posting-language-chips').innerHTML='';$('#posting-language-choices').innerHTML='';$('#posting-language-empty').hidden=true;$('#posting-language-more').hidden=true;$('#posting-language-done').disabled=true;$('#posting-language-load-state').hidden=false;$('#posting-language-load-state').textContent=I18n.text('Loading languages…');$('#posting-language-count').textContent='';$('#posting-language-any').setAttribute('aria-pressed',String(!ui.draft.size));const dialog=$('#posting-language-dialog');if(!dialog.open)dialog.showModal();$('#posting-language-find').focus();try{await loadPostingLanguageCatalogue();if(!dialog.open)return;renderPostingLanguageChoices(true);renderPostingLanguageControls();}catch{$('#posting-language-load-state').innerHTML=`${I18n.text('Could not load languages.')} <button type="button" data-retry-posting-languages>${I18n.text('Try again')}</button>`;}}
function initPostingLanguages(){
// Explicit fictional language fixtures, not a language inference from production locations.
const fixtureLanguages={CHE:['de','fr','it'],DEU:['de'],AUT:['de'],FRA:['fr'],JPN:['ja'],BRA:['pt'],MEX:['es'],CHL:['es'],NLD:['nl'],DNK:['da'],SWE:['sv'],NOR:['no'],FIN:['fi'],IDN:['id'],KEN:['sw'],NGA:['yo'],EGY:['ar'],IND:['hi'],ZAF:['af'],CAN:['fr']};
for(const [index,job]of jobs.entries()){const local=fixtureLanguages[job.country]||['en'];const code=local[index%local.length];job.postingLanguages=index%3===0?[code]:index%5===0&&code!=='en'?['en',code]:['en'];}
renderPostingLanguageControls();if(postingLanguages.size)loadPostingLanguageCatalogue().then(renderPostingLanguageControls).catch(()=>{});
document.addEventListener('click',event=>{if(event.target.closest('[data-posting-languages]')){openPostingLanguagePicker();return;}if(event.target.closest('[data-retry-posting-languages]')){openPostingLanguagePicker();return;}const remove=event.target.closest('[data-remove-posting-language]');if(remove){const code=remove.dataset.removePostingLanguage;postingLanguageUI.draft.delete(code);renderPostingLanguageChoices();$('#posting-language-find').focus();}});
$('#posting-language-find').addEventListener('input',()=>{renderPostingLanguageChoices(true);$('#posting-language-list').scrollTop=0;});
$('#posting-language-choices').addEventListener('change',event=>{if(!event.target.matches('input[type=checkbox]'))return;const input=event.target,scroll=$('#posting-language-list').scrollTop;input.checked?postingLanguageUI.draft.add(input.value):postingLanguageUI.draft.delete(input.value);renderPostingLanguageChoices();$('#posting-language-list').scrollTop=scroll;$(`#posting-language-choices input[value="${input.value}"]`)?.focus({preventScroll:true});});
$('#posting-language-any').addEventListener('click',()=>{postingLanguageUI.draft.clear();renderPostingLanguageChoices();});
$('#posting-language-more').addEventListener('click',()=>{const first=postingLanguageUI.limit;postingLanguageUI.limit+=60;renderPostingLanguageChoices();$$('#posting-language-choices input')[first]?.focus();});
$('#posting-language-done').addEventListener('click',()=>{postingLanguages=new Set(postingLanguageUI.draft);persist();renderPostingLanguageControls();resetFeed();$('#posting-language-dialog').close();announce(I18n.text('Posting languages updated.'));});
$('#posting-language-dialog').addEventListener('close',()=>{if(postingLanguageUI.opener?.isConnected)postingLanguageUI.opener.focus({preventScroll:true});});
}
